package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Extension;
import org.eclipse.rdf4j.query.algebra.ExtensionElem;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.impl.BlankNodeAllocationScope;
import org.eclipse.rdf4j.query.impl.RemoteBNode;
import org.junit.jupiter.api.Test;

class PackedPhysicalSourceIdentityTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final int FORMAT_BYTES = 1_000_000;

	@Test
	void exactSourceDistinguishesCollidingAndSeparatorBearingRdfContent() {
		assertEquals("Aa".hashCode(), "BB".hashCode());
		assertNotEquals(source(VF.createLiteral("Aa")), source(VF.createLiteral("BB")));
		assertNotEquals(source(VF.createLiteral("a|b;c\\d")), source(VF.createLiteral("a|b;c-d")));
		assertNotEquals(source(VF.createLiteral("x", "en")), source(VF.createLiteral("x", "fr")));
	}

	@Test
	void parameterizedSourceIncludesActualBoundValues() {
		PackedQuery one = PackedQueryCodec.encodeForParameterizedPlanning(expression(VF.createLiteral("one")), null);
		PackedQuery two = PackedQueryCodec.encodeForParameterizedPlanning(expression(VF.createLiteral("two")), null);
		assertTrue(one.parameterVector().size() > 0, "fixture must exercise invocation-local parameter references");
		assertNotEquals(source(one), source(two));
		assertEquals(source(one), source(PackedQueryCodec.encodeForParameterizedPlanning(
				expression(VF.createLiteral("one")), null)));
	}

	@Test
	void nestedSharedTriplesRetainAllOrdinaryContent() {
		Value child = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createLiteral("value"));
		Value shared = VF.createTripleTerm(VF.createIRI("urn:subject"), VF.createIRI("urn:outer"), child);
		assertNotNull(source(shared));
		assertEquals(source(shared), source(shared));
		Value different = VF.createTripleTerm(VF.createIRI("urn:subject"), VF.createIRI("urn:other"), child);
		assertNotEquals(source(shared), source(different));
		TupleExpr repeated = new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(child), "first"),
				new ExtensionElem(new ValueConstant(child), "second"));
		assertNotNull(source(PackedQueryCodec.encode(repeated)), "two occurrences retain one shared object term");
	}

	@Test
	void anyRemoteOwnerAtAnyTripleDepthRefusesDurableAuthority() {
		for (boolean canonical : new boolean[] { false, true }) {
			for (Object namespace : new Object[] { new Object(), new Object() }) {
				BNode remote = (BNode) RemoteBNode.newResponseScope(
						new BlankNodeAllocationScope("alias-", ignored -> false), VF, namespace, canonical)
						.map(VF.createBNode("canonical"));
				BNode plain = VF.createBNode(remote.getID());
				assertEquals(remote, plain);
				assertNull(source(remote));
				assertNotNull(source(plain));
				Value nested = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"),
						VF.createTripleTerm(remote, VF.createIRI("urn:q"), plain));
				assertNull(source(nested));
				PackedQuery parameterized = PackedQueryCodec.encodeForParameterizedPlanning(expression(nested), null);
				assertNull(source(parameterized), "parameter markers must not hide nested remote ownership");
			}
		}
	}

	@Test
	void exactFormatLimitAndBudgetFailurePrecedeOutputAllocation() {
		PackedQuery query = PackedQueryCodec.encode(expression(VF.createLiteral("owned")));
		String source = source(query);
		assertNotNull(source);
		try (var memory = owner()) {
			assertEquals(source, new PackedQueryView(query).tryPhysicalSourceIdentity(memory, source.length()));
		}
		try (var memory = owner()) {
			assertNull(new PackedQueryView(query).tryPhysicalSourceIdentity(memory, source.length() - 1));
		}
		try (var zero = PackedCostTestSupport.providerMemory(new PackedPlannerLimits(1, Long.MAX_VALUE, 0))) {
			assertNull(new PackedQueryView(query).tryPhysicalSourceIdentity(zero, FORMAT_BYTES));
			assertEquals(0L, zero.retainedBytes());
		}
		try (var memory = owner()) {
			assertNull(new PackedQueryView(query).tryPhysicalSourceIdentity(memory, Integer.MIN_VALUE));
			assertEquals(0L, memory.retainedBytes());
		}
	}

	@Test
	void exactRealOwnerReservationFitsAndOneByteShortRefusesBeforeTheCopy() {
		PackedQueryView view = new PackedQueryView(PackedQueryCodec.encode(expression(VF.createLiteral("owned"))));
		long required;
		String expected;
		try (var memory = owner()) {
			expected = view.tryPhysicalSourceIdentity(memory, FORMAT_BYTES);
			assertNotNull(expected);
			required = memory.retainedBytes();
		}
		try (var exact = PackedCostTestSupport.providerMemory(
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, required))) {
			assertEquals(expected, view.tryPhysicalSourceIdentity(exact, FORMAT_BYTES));
			assertEquals(required, exact.retainedBytes());
		}
		try (var shortOwner = PackedCostTestSupport.providerMemory(
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, required - 1L))) {
			assertNull(view.tryPhysicalSourceIdentity(shortOwner, FORMAT_BYTES));
			assertTrue(shortOwner.retainedBytes() < required);
		}
	}

	@Test
	void ownerCloseRevokesFurtherSourceReservation() {
		var memory = owner();
		memory.close();
		assertFalse(memory.tryReserve(1L));
		assertNull(new PackedQueryView(PackedQueryCodec.encode(expression(VF.createLiteral("x"))))
				.tryPhysicalSourceIdentity(memory, FORMAT_BYTES));
	}

	private static String source(Value value) {
		return source(PackedQueryCodec.encode(expression(value)));
	}

	private static String source(PackedQuery query) {
		try (var memory = owner()) {
			return new PackedQueryView(query).tryPhysicalSourceIdentity(memory, FORMAT_BYTES);
		}
	}

	private static TupleExpr expression(Value value) {
		return new Extension(new SingletonSet(), new ExtensionElem(new ValueConstant(value), "result"));
	}

	private static PackedCostTestSupport.ProviderMemoryOwner owner() {
		return PackedCostTestSupport.providerMemory(new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE));
	}
}
